package main

import (
	"bytes"
	"encoding/json"
	"strings"
	"testing"
)

func TestRunEmptyQueueUsesEmptyArrays(t *testing.T) {
	var stdout, stderr bytes.Buffer
	if code := run(strings.NewReader(`{"prs":[]}`), &stdout, &stderr); code != 0 {
		t.Fatalf("run exit code = %d, stderr = %q", code, stderr.String())
	}
	if got, want := stdout.String(), "{\"waves\":[],\"blocked\":[]}\n"; got != want {
		t.Fatalf("stdout = %q, want %q", got, want)
	}
}

func TestPlanDiamondAndInputOrder(t *testing.T) {
	inputs := []string{
		`{"prs":[{"id":4,"deps":[2,3],"checks":"pass"},{"id":2,"deps":[1],"checks":"pass"},{"id":1,"deps":[],"checks":"pass"},{"id":3,"deps":[1],"checks":"pass"}]}`,
		`{"prs":[{"id":1,"deps":[],"checks":"pass"},{"id":3,"deps":[1],"checks":"pass"},{"id":2,"deps":[1],"checks":"pass"},{"id":4,"deps":[2,3],"checks":"pass"}]}`,
	}
	want := `{"waves":[[1],[2,3],[4]],"blocked":[]}`
	for _, input := range inputs {
		var stdout, stderr bytes.Buffer
		if code := run(strings.NewReader(input), &stdout, &stderr); code != 0 {
			t.Fatalf("run exit code = %d, stderr = %q", code, stderr.String())
		}
		if got := strings.TrimSpace(stdout.String()); got != want {
			t.Errorf("stdout = %s, want %s", got, want)
		}
	}
}

func TestPlanBlocksTransitively(t *testing.T) {
	input := `{"prs":[{"id":6,"deps":[5],"checks":"pass"},{"id":1,"deps":[],"checks":"fail"},{"id":5,"deps":[2],"checks":"pass"},{"id":3,"deps":[1],"checks":"pass"},{"id":4,"deps":[],"checks":"pass"},{"id":2,"deps":[1],"checks":"pass"}]}`
	var stdout, stderr bytes.Buffer
	if code := run(strings.NewReader(input), &stdout, &stderr); code != 0 {
		t.Fatalf("run exit code = %d, stderr = %q", code, stderr.String())
	}
	want := `{"waves":[[4]],"blocked":[1,2,3,5,6]}`
	if got := strings.TrimSpace(stdout.String()); got != want {
		t.Fatalf("stdout = %s, want %s", got, want)
	}
}

func TestInvalidInputExitsTwoWithDiagnosticAndNoOutput(t *testing.T) {
	tests := []struct {
		name  string
		input string
	}{
		{"duplicate IDs", `{"prs":[{"id":1,"deps":[],"checks":"pass"},{"id":1,"deps":[],"checks":"pass"}]}`},
		{"missing dependency", `{"prs":[{"id":1,"deps":[2],"checks":"pass"}]}`},
		{"cycle", `{"prs":[{"id":1,"deps":[2],"checks":"pass"},{"id":2,"deps":[1],"checks":"pass"}]}`},
		{"cycle through failed PR", `{"prs":[{"id":1,"deps":[2],"checks":"fail"},{"id":2,"deps":[1],"checks":"pending"}]}`},
		{"zero ID", `{"prs":[{"id":0,"deps":[],"checks":"pass"}]}`},
		{"negative ID", `{"prs":[{"id":-1,"deps":[],"checks":"pass"}]}`},
		{"bad status", `{"prs":[{"id":1,"deps":[],"checks":"unknown"}]}`},
		{"malformed JSON", `{"prs":`},
		{"trailing JSON", `{"prs":[]} {"prs":[]}`},
	}
	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			var stdout, stderr bytes.Buffer
			if code := run(strings.NewReader(tt.input), &stdout, &stderr); code != 2 {
				t.Fatalf("run exit code = %d, want 2; stderr = %q", code, stderr.String())
			}
			if stdout.Len() != 0 {
				t.Fatalf("stdout = %q, want empty", stdout.String())
			}
			if strings.TrimSpace(stderr.String()) == "" {
				t.Fatal("stderr is empty, want diagnostic")
			}
		})
	}
}

func TestPlanOutputIsJSON(t *testing.T) {
	result, err := plan(strings.NewReader(`{"prs":[{"id":2,"deps":[],"checks":"pending"}]}`))
	if err != nil {
		t.Fatal(err)
	}
	data, err := json.Marshal(result)
	if err != nil {
		t.Fatal(err)
	}
	if got, want := string(data), `{"waves":[],"blocked":[2]}`; got != want {
		t.Fatalf("marshaled result = %s, want %s", got, want)
	}
}

--- README ---
# mergequeue

`mergequeue` reads one dependency-aware merge queue from standard input and
writes its deterministic waves and blocked PR IDs as JSON.

Build and run it with:

```sh
go build -o mergequeue .
printf '%s\n' '{"prs":[{"id":4,"deps":[2,3],"checks":"pass"},{"id":1,"deps":[],"checks":"pass"},{"id":2,"deps":[1],"checks":"pass"},{"id":3,"deps":[1],"checks":"pass"}]}' | ./mergequeue
```

Output:

```json
{"waves":[[1],[2,3],[4]],"blocked":[]}
```

Failed or pending PRs, plus every PR depending on them, appear in `blocked`.
Invalid input prints a diagnostic to standard error, prints no result, and
exits with status 2.

--- SPEC ---
Build a dependency-aware merge-queue CLI in ordinary Go, using the standard library.
Read one JSON object from stdin: {"prs":[{"id":1,"deps":[],"checks":"pass"}]}.
IDs must be positive and unique. checks is pass, fail, or pending. A dependency must name a PR in the input. Reject malformed JSON, extra JSON values, invalid status, invalid IDs, duplicate IDs, missing dependencies and any cycle (including cycles among failed PRs), with exit 2, a useful stderr diagnostic and no stdout.
On valid input return {"waves":[[1,2],[3]],"blocked":[4,5]}. Each wave contains every passing PR whose dependencies were in earlier waves; ascending IDs per wave. Nonpassing PRs and everything transitively depending on them go into blocked, sorted. Empty arrays must be [], never null. Input order must not change the result. Empty queue works.
Supply tests and a short README with runnable input/output examples. The workflow will run an external black-box acceptance program and independent agent validation. Preserve every requirement; do not change the external acceptance program.

New requirement disclosed after the first successful base acceptance: add --parallel N to limit each wave to at most N ready PRs, choosing lowest IDs first. The default is unlimited. Reject missing, zero, negative, or non-integer N with exit 2 and no stdout. Document the flag.

--- WORKLOG ---
friction: apply_patch rejected a combined delete-and-add operation for main.go, so the replacement had to be applied as separate operations -> prefer separate delete/add patches when replacing a tiny fixture file.
decision: validate the complete dependency graph, including nonpassing nodes, for missing dependencies and cycles before calculating blocked propagation or waves -> preserves the assignment's requirement to reject cycles among failed or pending PRs.

